  utRecurring: () => { const tx = UX(), ym = PROC_TODAY.slice(0, 7); const due = tx.conns.filter(c => utVis(c) && c.status === 'Active' && utType(c.type).recurring && c.cycle === 'Monthly' && !tx.bills.some(b => b.conn === c.id && b.billDate.slice(0, 7) === ym)); if (!due.length) return toast('Every monthly connection already has a bill for this month.', 'bad'); askReason(`Generate ${due.length} recurring draft bills for ${MON[+ym.slice(5) - 1]}`, 'Drafts are created from each connection\'s average bill; coordinators complete readings and amounts before submitting.', async r => { const tx2 = Store.clone(UX()); due.forEach(c => { const d = { id: 'B' + Date.now().toString(36) + c.id, no: utNo(tx2, 'UB'), kind: 'bill', conn: c.id, bid: c.bid, type: c.type, billNo: '', periodFrom: ym + '-01', periodTo: PROC_TODAY, billDate: PROC_TODAY, dueDate: pcAddDays(PROC_TODAY, 15), prevOut: 0, current: c.avgBill, penalty: 0, discount: 0, prevRead: (utHistory(c.id).slice(-1)[0] || {}).currRead || null, currRead: null, units: null, rate: null, fixed: 0, surcharge: 0, tax: 0, priority: 'Normal', remarks: 'Recurring template', attach: '', createdBy: App.user.id, createdByName: App.user.name, createdAt: nowIso(), status: 'Draft', level: 0, chain: [], log: [], amount: c.avgBill }; utLog(d, 'Created from recurring template'); tx2.bills.unshift(d); }); await utSave(tx2); audit('Utilities', 'Recurring bills generated', { new: `${due.length} drafts for ${ym}`, reason: r }); toast(`${due.length} draft bills created.`); }); },
  utTankerForm: () => { const M = UM(), brs = DATA.branches.filter(b => !b.closed && utScope().has(b.id)).map(b => [b.id, b.name]); modal('Record water tanker delivery', `<div class="form-grid">${pcFld('Branch / property', pcSel('wt_bid', brs, pcMyBranch()))}${pcFld('Date & time', `<input id="wt_date" type="date" value="${PROC_TODAY}" max="${PROC_TODAY}"><input id="wt_time" type="time" value="09:00">`)}${pcFld('Tanker vendor', pcSel('wt_vendor', [...new Set(M.tankerRates.map(r => r.vendor))], ''))}${pcFld('Vehicle number', '<input id="wt_veh" placeholder="TS09 T1234">')}${pcFld('Capacity (litres)', pcSel('wt_cap', [...new Set(M.tankerRates.map(r => String(r.capacity)))], '5000'))}${pcFld('Number of tankers', '<input id="wt_n" type="number" min="1" value="1">')}${pcFld('Rate per tanker (₹, from rate master)', '<input id="wt_rate" type="number" min="0" placeholder="Auto from vendor + capacity">')}${pcFld('Water type', pcSel('wt_type', ['Drinking', 'Domestic', 'Construction', 'Other'], 'Domestic'))}${pcFld('Delivery location', '<input id="wt_loc" value="Overhead tank – main">')}${pcFld('Receiving staff', `<input id="wt_recv" value="${esc(App.user.name.replace(' (demo)', ''))}">`)}${pcFld('Photo / delivery challan', '<input id="wt_file" type="file">')}${pcFld('Invoice / cash voucher no.', '<input id="wt_inv">')}</div><label class="fld"><span>Remarks</span><input id="wt_rem"></label>`, `<button class="btn" data-act="closeModal">Cancel</button><button class="btn primary" data-act="utTankerOk">Record delivery</button>`); },
  utTankerOk: async () => { const M = UM(), bid = v('wt_bid'), vendor = v('wt_vendor'), cap = +v('wt_cap'), n = +v('wt_n') || 0; if (!bid || !vendor || !(n > 0)) return toast('Enter the branch, vendor and number of tankers.', 'bad'); const rm = M.tankerRates.find(r => r.vendor === vendor && r.capacity === cap); const rate = +v('wt_rate') || (rm ? rm.rate : 0); if (!(rate > 0)) return toast('No rate in the master for this vendor and capacity – enter the rate.', 'bad'); if (!(v('wt_recv') || '').trim()) return toast('Enter the receiving staff name.', 'bad'); const tx = Store.clone(UX()); const f = document.getElementById('wt_file'); const t = { id: 'T' + Date.now().toString(36), no: utNo(tx, 'WT'), bid, date: v('wt_date'), at: v('wt_date') + 'T' + (v('wt_time') || '09:00') + ':00+05:30', vendor, vehicle: v('wt_veh'), capacity: cap, count: n, rate, total: n * rate, waterType: v('wt_type'), location: v('wt_loc'), receiver: v('wt_recv'), attach: f && f.files[0] ? f.files[0].name : '', voucher: v('wt_inv'), status: 'Pending', remarks: v('wt_rem'), createdBy: App.user.id }; tx.tankers.unshift(t); await utSave(tx); const month = tx.tankers.filter(x => x.bid === bid && x.date.slice(0, 7) === PROC_TODAY.slice(0, 7)).reduce((s, x) => s + x.count, 0); if (month > M.cfg.tankerMonthlyMax) utNotify(PROC_FIN_ROLES.flatMap(r => pcUsersByRole(r)), `${utBr(bid)}: ${month} water tankers this month – above the ${M.cfg.tankerMonthlyMax} threshold`, t.id, 'ut_meters'); audit('Utilities', 'Water tanker recorded', { new: `${t.no} · ${utBr(bid)} · ${n} × ${cap} L · ${INR(t.total)} · ${vendor}` }); closeModal(); toast(t.no + ' recorded.'); },
  utTankerPay: t => pcRemark('Pay tanker from petty cash', 'A paid petty-cash voucher is created for the branch custodian.', false, async rem => { const tx = Store.clone(UX()), x = tx.tankers.find(y => y.id === t.dataset.k); if (x.total > UM().cfg.pettyMax) return toast(`Above the petty-cash limit ${INR(UM().cfg.pettyMax)} – pay through Finance.`, 'bad'); const ctx = Store.clone(CT()); if (x.total > cbBalance(x.bid, '9999-12-31', ctx)) return toast('Insufficient petty cash at the branch.', 'bad'); const vch = { id: 'V' + Date.now().toString(36), no: cbNo(ctx, 'PV'), kind: 'voucher', bid: x.bid, dept: 'Administration', cc: `CC-${x.bid}-UTL`, cat: 'OTP', date: PROC_TODAY, payee: x.vendor, purpose: `Water tanker ${x.no} · ${x.count} × ${x.capacity} L`, amount: x.total, bill: x.voucher || x.no, vendor: x.vendor, attach: x.attach, tax: 0, emergency: false, emergencyReason: '', exception: '', remarks: rem, createdBy: App.user.id, createdByName: App.user.name, createdAt: nowIso(), status: 'Paid', paidAt: nowIso(), paidBy: App.user.name, level: 0, chain: [{ role: 'Finance', label: 'Utilities approval', status: 'Approved', by: App.user.name, at: nowIso(), remark: 'Tanker payment' }], log: [] }; cbLog(vch, 'Paid in cash', 'Water tanker ' + x.no); cbPost(ctx, x.bid, -x.total, 'Payment', vch.no, { cat: 'OTP' }); ctx.vouchers.unshift(vch); await Store.put('pcash_tx', ctx); x.status = 'Paid'; x.voucher = vch.no; await utSave(tx); audit('Utilities', 'Tanker paid (petty cash)', { new: `${x.no} · ${vch.no} · ${INR(x.total)}`, reason: rem }); }),
