Object.assign(UT_ACT, {
  utTypeForm: t => { const id = t.dataset.k, x = id === 'new' ? { id: '', name: '', cat: 'Other', expHead: '', bud: 'UTL', freq: 'Monthly', meter: false, recurring: true, alertDays: 7, docs: 'Bill / invoice', tax: false, approval: 'Standard', provKind: '', active: true } : utType(id); modal(id === 'new' ? 'Add utility type' : 'Edit utility type · ' + x.name, `<div class="form-grid">${pcFld('Code', `<input id="ty_id" value="${esc(x.id)}" maxlength="4" ${id === 'new' ? '' : 'disabled'}>`)}${pcFld('Name', `<input id="ty_name" value="${esc(x.name)}">`)}${pcFld('Utility category', pcSel('ty_cat', ['Power', 'Water', 'Communication', 'Statutory', 'Property', 'Services', 'Other'], x.cat))}${pcFld('Expense head', `<input id="ty_exp" value="${esc(x.expHead)}">`)}${pcFld('Budget head · cost-centre mapping', `<input id="ty_bud" value="${esc(x.bud)}">`)}${pcFld('Payment frequency', pcSel('ty_freq', UT_CYCLES, x.freq))}${pcFld('Approval workflow', pcSel('ty_appr', ['Standard', 'Strict (always full route)'], x.approval))}${pcFld('Due-date alert (days before)', `<input id="ty_alert" type="number" min="0" value="${x.alertDays}">`)}${pcFld('Required documents', `<input id="ty_docs" value="${esc(x.docs)}">`)}${pcFld('Tax applicable', pcSel('ty_tax', [['0', 'No'], ['1', 'Yes (GST)']], x.tax ? '1' : '0'))}${pcFld('Meter reading required', pcSel('ty_meter', [['0', 'No'], ['1', 'Yes']], x.meter ? '1' : '0'))}${pcFld('Recurring bill entry', pcSel('ty_rec', [['1', 'Automatic template'], ['0', 'Manual']], x.recurring ? '1' : '0'))}</div>`, `<button class="btn" data-act="closeModal">Cancel</button><button class="btn primary" data-act="utTypeOk" data-k="${id}">Save</button>`); },
  utTypeOk: t => { const id = t.dataset.k, code = (v('ty_id') || '').trim().toUpperCase(), name = (v('ty_name') || '').trim(); if (!/^[A-Z]{2,4}$/.test(code) || !name) return toast('Enter a 2–4 letter code and name.', 'bad'); const M = Store.clone(UM()); if (id === 'new' && M.types.some(x => x.id === code)) return toast('Code in use.', 'bad'); const o = { name, cat: v('ty_cat'), expHead: v('ty_exp') || 'Utilities – ' + name, bud: v('ty_bud') || 'UTL', freq: v('ty_freq'), approval: v('ty_appr').startsWith('Strict') ? 'Strict' : 'Standard', alertDays: +v('ty_alert') || 7, docs: v('ty_docs'), tax: v('ty_tax') === '1', meter: v('ty_meter') === '1', recurring: v('ty_rec') === '1' }; askReason(id === 'new' ? 'Add utility type' : 'Update utility type', name, async r => { if (id === 'new') M.types.push(Object.assign({ id: code, active: true, provKind: '' }, o)); else Object.assign(M.types.find(x => x.id === id), o); await Store.put('util', M); audit('Utilities', 'Utility type saved', { new: code + ' · ' + name, reason: r }); }); },
  utTypeTog: t => askReason('Change utility type status', utType(t.dataset.k).name, async r => { const M = Store.clone(UM()), x = M.types.find(y => y.id === t.dataset.k); x.active = !x.active; await Store.put('util', M); audit('Utilities', 'Utility type ' + (x.active ? 'activated' : 'deactivated'), { new: x.name, reason: r }); }),
  utProvForm: t => { const id = t.dataset.k, p = id === 'new' ? { name: '', types: [], region: 'All', contact: '', phone: '', email: '', rating: 4, active: true } : utProv(id); modal(id === 'new' ? 'Add service provider' : 'Edit provider · ' + p.name, `<div class="form-grid">${pcFld('Name', `<input id="pv_name" value="${esc(p.name)}">`)}${pcFld('Region', pcSel('pv_region', ['All'].concat([...new Set(DATA.branches.map(b => b.region))]), p.region))}${pcFld('Contact person', `<input id="pv_contact" value="${esc(p.contact)}">`)}${pcFld('Phone', `<input id="pv_phone" value="${esc(p.phone)}">`)}${pcFld('Email', `<input id="pv_email" value="${esc(p.email)}">`)}${pcFld('Rating (0–5)', `<input id="pv_rating" type="number" min="0" max="5" step="0.1" value="${p.rating}">`)}${pcFld('Status', pcSel('pv_active', [['1', 'Active'], ['0', 'Inactive']], p.active ? '1' : '0'))}</div><label class="fld"><span>Services</span><select id="pv_types" multiple size="6">${UM().types.map(t => `<option value="${t.id}" ${p.types.includes(t.id) ? 'selected' : ''}>${esc(t.name)}</option>`).join('')}</select></label>`, `<button class="btn" data-act="closeModal">Cancel</button><button class="btn primary" data-act="utProvOk" data-k="${id}">Save</button>`); },
  utProvOk: t => { const id = t.dataset.k, o = { name: (v('pv_name') || '').trim(), region: v('pv_region'), contact: v('pv_contact'), phone: v('pv_phone'), email: v('pv_email'), rating: +v('pv_rating') || 0, active: v('pv_active') === '1', types: [...document.getElementById('pv_types').selectedOptions].map(x => x.value) }; if (!o.name || !o.types.length) return toast('Enter the name and at least one service.', 'bad'); askReason(id === 'new' ? 'Add provider' : 'Update provider', o.name, async r => { const M = Store.clone(UM()); if (id === 'new') M.providers.push(Object.assign({ id: 'SP' + Date.now().toString(36) }, o)); else Object.assign(M.providers.find(p => p.id === id), o); await Store.put('util', M); audit('Utilities', 'Service provider saved', { new: o.name, reason: r }); }); },
  utTankRateAdd: () => { const vendor = (v('tr_v') || '').trim(), cap = +v('tr_c'), rate = +v('tr_r'); if (!vendor || !(cap > 0) || !(rate > 0)) return toast('Enter vendor, capacity and rate.', 'bad'); askReason('Add tanker rate', `${vendor} · ${cap} L · ${INR(rate)}`, async r => { const M = Store.clone(UM()); const ex = M.tankerRates.find(x => x.vendor === vendor && x.capacity === cap); if (ex) ex.rate = rate; else M.tankerRates.push({ vendor, capacity: cap, rate }); await Store.put('util', M); audit('Utilities', 'Tanker rate saved', { new: `${vendor} · ${cap} L · ${INR(rate)}`, reason: r }); }); },
  utBudgetForm: () => { const brs = DATA.branches.filter(b => !b.closed && utScope().has(b.id)).map(b => [b.id, b.name]); if (UT_CORP()) brs.unshift(['CORP', 'Corporate Office']); modal('Set utility budget', `<div class="form-grid">${pcFld('Branch', pcSel('ub_bid', brs, pcMyBranch() || 'CORP'))}${pcFld('Utility type', pcSel('ub_type', UM().types.map(t => [t.id, t.name]), 'ELE'))}${pcFld('Annual budget (₹)', '<input id="ub_amt" type="number" min="0" step="1000">')}</div>`, `<button class="btn" data-act="closeModal">Cancel</button><button class="btn primary" data-act="utBudgetOk">Save</button>`); },
  utBudgetOk: () => { const bk = v('ub_bid'), type = v('ub_type'), amt = +v('ub_amt') || 0; askReason('Set utility budget', `${bk === 'CORP' ? 'Corporate Office' : brName(bk)} · ${utType(type).name} · ${INR(amt)}`, async r => { const M = Store.clone(UM()); M.budgets[bk] = M.budgets[bk] || {}; const old = M.budgets[bk][type] || 0; M.budgets[bk][type] = amt; await Store.put('util', M); audit('Utilities', 'Utility budget set', { old: INR(old), new: `${bk} · ${utType(type).name} · ${INR(amt)}`, reason: r }); }); },
  utCfgSave: t => { const M = Store.clone(UM()), c = M.cfg, old = JSON.stringify(c); if (t.dataset.k === 'tank') c.tankerMonthlyMax = +v('t_max') || 20; else { Object.assign(c, { simpleBelow: +v('r_simple') || 0, financeAlways: v('r_fin') === '1', cfoAbove: +v('r_cfo') || 0, pettyMax: +v('r_petty') || 0, tdsRentAbove: +v('r_tdsa') || 0, tdsRentPct: +v('r_tdsp') || 0, leaseAlertDays: +v('r_lease') || 90, allowSelf: v('r_self') === '1', adminOverride: v('r_adm') === '1', dueAlertDays: (v('r_due') || '7').split(',').map(x => +x.trim()).filter(x => x > 0), highUsePct: +v('r_high') || 25, spikePct: +v('r_spike') || 30, renewalAlertDays: +v('r_ren') || 45, meterDay: +v('r_meter') || 1, notifyEmail: v('r_mail') === '1' }); Object.keys(c.numbering).forEach(k => c.numbering[k] = (v('n_' + k) || k).trim().toUpperCase()); } askReason('Save utilities settings', 'Applies to new entries; documents already in approval keep their route.', async r => { await Store.put('util', M); audit('Utilities', 'Settings changed', { old: old.slice(0, 400), new: JSON.stringify(M.cfg).slice(0, 400), reason: r }); toast('Settings saved.'); }); }
});
